  vi.stubGlobal(
    "fetch",
    vi.fn((input: RequestInfo | URL, init?: RequestInit) => {
      const reply = answer(input, init);
      if (init?.method !== "POST") return reply;
      return new Promise<Response>((resolve) => {
        held.push(() => {
          resolve(reply);
        });
      });
    }),
  );
  return () => {
    held.shift()?.();
